/**
 * Brand marks — the same lockup the marketing site uses (rooftopauto.com):
 * "Shelter" chevron-over-coupe mark + the italic ROOFTOP/AUTO wordmark.
 *
 * The wordmark is Archivo 900 italic **converted to outlines**, deliberately.
 * The app ships no webfonts (see the note in src/app/layout.tsx) and the brand
 * rules forbid setting the wordmark in a substitute face — outlining is the only
 * way to have both. Never hand-edit the path data; regenerate it from
 * brand/svg/lockup-italic-*.svg if the wordmark ever changes.
 *
 * Geometry is copied verbatim from site/index.html so the two never drift.
 */

const CHEVRON = '#3D8BFF';
const BODY = '#F4F7FA';

/** Chevron + coupe, sized for dark backgrounds. Below 20px use the favicon art instead. */
export function RooftopMark({ size = 30, className }: { size?: number; className?: string }) {
  return (
    <svg
      width={size}
      height={Math.round((size * 26) / 30)}
      viewBox="2 3 60 52"
      className={className}
      aria-hidden="true"
    >
      <path
        d="M5 25 L32 6 L59 25"
        fill="none"
        stroke={CHEVRON}
        strokeWidth="5.5"
        strokeLinecap="square"
        strokeLinejoin="miter"
      />
      <path
        fillRule="evenodd"
        fill={BODY}
        d="M6 47 Q6 42 11 40.5 L23.5 36 L29.5 30.5 Q32.5 28.5 38.5 29.5 L47 33 Q54.5 36 57 41 Q59 43 58.5 47 Z M28.6 36.2 L32.2 32.6 Q34.2 31.7 37.4 32.3 L43.6 34.6 Z M11.4 47 a7.6 7.6 0 1 0 15.2 0 a7.6 7.6 0 1 0 -15.2 0 Z M37.4 47 a7.6 7.6 0 1 0 15.2 0 a7.6 7.6 0 1 0 -15.2 0 Z"
      />
      <path
        fillRule="evenodd"
        fill={BODY}
        d="M13.6 47 a5.4 5.4 0 1 0 10.8 0 a5.4 5.4 0 1 0 -10.8 0 Z M16.9 47 a2.1 2.1 0 1 0 4.2 0 a2.1 2.1 0 1 0 -4.2 0 Z M39.6 47 a5.4 5.4 0 1 0 10.8 0 a5.4 5.4 0 1 0 -10.8 0 Z M42.9 47 a2.1 2.1 0 1 0 4.2 0 a2.1 2.1 0 1 0 -4.2 0 Z"
      />
    </svg>
  );
}

