/**
 * Mark + wordmark + "A Litespeed company", the nav lockup from the marketing site.
 * `compact` is the 240px admin sidebar; the default is the roomier sign-in size.
 */
export function RooftopLockup({ compact = false }: { compact?: boolean }) {
  return (
    <div className="flex items-center" style={{ gap: compact ? 9 : 11 }}>
      <RooftopMark size={compact ? 30 : 38} className="shrink-0" />
      <div className="flex flex-col">
        <RooftopWordmark height={compact ? 13 : 17} />
        <span
          className="font-semibold uppercase text-ink-400"
          style={{
            fontSize: compact ? 8.5 : 9.5,
            letterSpacing: compact ? 1.3 : 1.7,
            marginTop: compact ? 4 : 5,
            lineHeight: 1,
          }}
        >
          A Litespeed company
        </span>
      </div>
    </div>
  );
}
